import pandas as pd, numpy as np, glob
from scipy.optimize import least_squares
files=sorted(glob.glob('train/*.csv'))
D={f:pd.read_csv(f) for f in files}
def sim_q(p,d):
    Kq,Kd,Tq=p
    t=d.time_s.values; V=d.voltage_pu.values; vs=d.voltage_setpoint_pu.values
    V0=V[0]; vs0=vs[0]; Q0=d.reactive_power_pu.values[0]
    x=0.0; out=np.empty(len(V)); dt=1e-3
    for i in range(len(V)):
        out[i]=Q0+x+Kd*(V[i]-V0)
        x+=dt*(Kq*((vs[i]-vs0)-(V[i]-V0))-x)/Tq
    return out
def resq(p,fl):
    return np.concatenate([sim_q(p,D[f])-D[f].reactive_power_pu.values for f in fl])
sel=[f for f in files if 'vref' in f or 'amb' in f]
r=least_squares(resq,[2,2,2],args=(sel,),bounds=([0,-10,0.01],[50,50,60]))
print(r.x, np.sqrt(np.mean(r.fun**2)))
for f in files:
    e=resq(r.x,[f]); print(f, np.sqrt(np.mean(e**2)))

